import { useState, useEffect } from "react";
import "./App.css";

function App() {
    const initialValues = {
        username: "",
        email: "",
        password: "",
        confirmPassword: "",
    };

    const [formValues, setFormValues] = useState(initialValues);
    const [formErrors, setFormErrors] = useState({});
    const [isSubmit, setIsSubmit] = useState(false);
    const [apiResponse, setApiResponse] = useState(null);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormValues({ ...formValues, [name]: value });
    };

    const validate = (values) => {
        const errors = {};
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/i;

        if (!values.username) {
            errors.username = "Username is required!";
        }

        if (!values.email) {
            errors.email = "Email is required!";
        } else if (!emailRegex.test(values.email)) {
            errors.email = "This is not a valid email format!";
        }

        if (!values.password) {
            errors.password = "Password is required";
        } else if (values.password.length < 4) {
            errors.password = "Password must be more than 4 characters";
        } else if (values.password.length > 10) {
            errors.password = "Password cannot exceed 10 characters";
        }

        if (values.password !== values.confirmPassword) {
            errors.confirmPassword = "Those passwords didn’t match. Try again.";
        }

        return errors;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const errors = validate(formValues);
        setFormErrors(errors);
        setIsSubmit(true);

        if (Object.keys(errors).length === 0) {
            try {
                const response = await fetch("https://reqres.in/api/register", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                    },
                    body: JSON.stringify({
                        email: formValues.email,
                        password: formValues.password,
                    }),
                });

                if (!response.ok) {
                    throw new Error("API request failed");
                }

                const data = await response.json();
                console.log("API success:", data);
                setApiResponse("Signed up successfully!");
            } catch (error) {
                console.error("API error:", error);
                setApiResponse("Failed to sign up. Please try again.");
            }
        }
    };

    useEffect(() => {
        if (Object.keys(formErrors).length === 0 && isSubmit) {
            console.log("Form Submitted:", formValues);
        }
    }, [formErrors, formValues, isSubmit]);

    return (
        <div className="container">
            {apiResponse && (
                <div className="ui message success">{apiResponse}</div>
            )}

            <form onSubmit={handleSubmit}>
                <h1>Sign Up</h1>
                <div className="ui divider"></div>
                <div className="ui form">
                    <div className="field">
                        <label>Username</label>
                        <input
                            type="text"
                            name="username"
                            placeholder="Choose a username"
                            value={formValues.username}
                            onChange={handleChange}
                        />
                        <p>{formErrors.username}</p>
                    </div>

                    <div className="field">
                        <label>Email</label>
                        <input
                            type="text"
                            name="email"
                            placeholder="Email"
                            value={formValues.email}
                            onChange={handleChange}
                        />
                        <p>{formErrors.email}</p>
                    </div>

                    <div className="field">
                        <label>Password</label>
                        <input
                            type="password"
                            name="password"
                            placeholder="Password"
                            value={formValues.password}
                            onChange={handleChange}
                        />
                        <p>{formErrors.password}</p>
                    </div>

                    <div className="field">
                        <label>Confirm Password</label>
                        <input
                            type="password"
                            name="confirmPassword"
                            placeholder="Confirm password"
                            value={formValues.confirmPassword}
                            onChange={handleChange}
                        />
                        <p>{formErrors.confirmPassword}</p>
                    </div>

                    <button className="fluid ui button blue" type="submit">
                        Submit
                    </button>
                </div>
            </form>

            <div className="text">
                Already have an account? <span>Login</span>
            </div>
        </div>
    );
}

export default App;
